// Фильтр письма Min/Max: отправитель, тема, ровно один Excel.
// Idempotency key: minmax-<mailbox>-<UID>-<имя файла>-<размер>-<sha256-16>.
// UID берётся из $json.attributes.uid (Email Trigger (IMAP) v2, формат resolved).
// ВАЖНО: IMAP-нода n8n НЕ возвращает UIDVALIDITY (проверено по исходному коду
// n8n: EmailReadImapV2.node.ts + v2/utils.ts), поэтому вместо UIDVALIDITY в ключ
// включены первые 16 hex-символов sha256 содержимого вложения. Это защищает от
// коллизии при пересоздании ящика (смена UIDVALIDITY → переиспользование UID):
// у другого письма другой sha256, значит и другой ключ.
const allowedSender = String($env.MINMAX_ALLOWED_SENDER || '').trim().toLowerCase();
const subjectPattern = String($env.MINMAX_SUBJECT_PATTERN || '').trim().toLowerCase();
const maxBytes = Number($env.MINMAX_MAX_ATTACHMENT_BYTES) || 20 * 1024 * 1024;
const mailbox = String($env.MINMAX_IMAP_MAILBOX || 'INBOX');

const from = String(($json.from && $json.from.text) || $json.from || '').toLowerCase();
const subject = String($json.subject || '');
// Email Trigger (IMAP) v2 кладёт UID в $json.attributes.uid.
// Фолбэки: $json.uid (старые/сторонние ноды), $json.messageId (RFC-заголовок).
const messageUid = String(
  ($json.attributes && $json.attributes.uid) ??
  $json.uid ??
  $json.messageId ??
  ''
);

// SHA-256 на чистом JS: Code node не позволяет require('crypto') без
// NODE_FUNCTION_ALLOW_BUILTIN, а от этой настройки workflow не зависит.
function sha256hex(data) {
  const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) | 0;
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
  ];
  let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;
  const bitLen = data.length * 8;
  const paddedLen = Math.ceil((data.length + 1 + 8) / 64) * 64;
  const msg = new Uint8Array(paddedLen);
  msg.set(data);
  msg[data.length] = 0x80;
  const dv = new DataView(msg.buffer);
  dv.setUint32(paddedLen - 8, Math.floor(bitLen / 0x100000000), false);
  dv.setUint32(paddedLen - 4, bitLen >>> 0, false);
  const w = new Uint32Array(64);
  for (let off = 0; off < paddedLen; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = (rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3)) | 0;
      const s1 = (rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10)) | 0;
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    h0 = (h0 + a) | 0; h1 = (h1 + b) | 0; h2 = (h2 + c) | 0; h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0; h5 = (h5 + f) | 0; h6 = (h6 + g) | 0; h7 = (h7 + h) | 0;
  }
  return [h0, h1, h2, h3, h4, h5, h6, h7]
    .map(x => ('00000000' + (x >>> 0).toString(16)).slice(-8))
    .join('');
}

const sanitize = value => {
  const cleaned = String(value ?? '')
    .replace(/[^A-Za-z0-9._:-]+/g, '_')
    .replace(/^_+|_+$/g, '');
  return (cleaned || 'na').slice(0, 120);
};
const buildKey = (attachmentName, size, contentHash) => [
  'minmax',
  sanitize(mailbox),
  sanitize(messageUid),
  sanitize(attachmentName),
  String(Number(size) || 0),
  contentHash
].join('-').slice(0, 512);

// sha256-16 содержимого вложения; 'na', если данные недоступны
// (например, binary-режим filesystem без data в $binary) — тогда
// уникальность ключа опирается на UID + имя + размер.
const hashBinary = entry => {
  if (entry && entry.data) {
    return sha256hex(Buffer.from(String(entry.data), 'base64')).slice(0, 16);
  }
  return 'na';
};

const base = {
  mailbox,
  messageUid,
  sender: from,
  subject,
  receivedDate: $json.date ?? null
};

if (!allowedSender || !from.includes(allowedSender)) {
  return [{ json: { ...base, outcome: 'ignored', reasonCode: 'SENDER_NOT_ALLOWED', idempotencyKey: buildKey('no-attachment', 0, 'na') } }];
}
if (!subjectPattern || !subject.toLowerCase().includes(subjectPattern)) {
  return [{ json: { ...base, outcome: 'ignored', reasonCode: 'SUBJECT_MISMATCH', idempotencyKey: buildKey('no-attachment', 0, 'na') } }];
}

const binary = $binary || {};
const names = Object.keys(binary);
if (names.length === 0) {
  return [{ json: { ...base, outcome: 'ignored', reasonCode: 'NO_ATTACHMENT', idempotencyKey: buildKey('no-attachment', 0, 'na') } }];
}
const excelNames = names.filter(name => {
  const fileName = String(binary[name]?.fileName || '').toLowerCase();
  return fileName.endsWith('.xlsx') || fileName.endsWith('.xls');
});
if (excelNames.length === 0) {
  return [{ json: { ...base, outcome: 'rejected', reasonCode: 'ATTACHMENT_TYPE_UNSUPPORTED', idempotencyKey: buildKey(binary[names[0]]?.fileName || names[0], 0, hashBinary(binary[names[0]])) } }];
}
if (excelNames.length > 1) {
  return [{ json: { ...base, outcome: 'rejected', reasonCode: 'MULTIPLE_ATTACHMENTS', idempotencyKey: buildKey(binary[excelNames[0]]?.fileName || excelNames[0], 0, hashBinary(binary[excelNames[0]])) } }];
}

const binaryKey = excelNames[0];
const attachment = binary[binaryKey];
const attachmentName = String(attachment.fileName || 'report.xlsx');
let size = Number(attachment.fileSize ?? attachment.fileSizeBytes ?? 0) || 0;
let bytes = null;
if (attachment.data) {
  bytes = Buffer.from(attachment.data, 'base64');
  size = bytes.length;
}
const contentHash = bytes ? sha256hex(bytes).slice(0, 16) : 'na';
if (size > maxBytes) {
  return [{ json: { ...base, outcome: 'rejected', reasonCode: 'ATTACHMENT_TOO_LARGE', idempotencyKey: buildKey(attachmentName, size, contentHash) } }];
}
if (bytes) {
  const isXlsx = bytes.length >= 4 && bytes[0] === 0x50 && bytes[1] === 0x4b && bytes[2] === 0x03 && bytes[3] === 0x04;
  const isXls = bytes.length >= 8 && bytes[0] === 0xd0 && bytes[1] === 0xcf && bytes[2] === 0x11 && bytes[3] === 0xe0 && bytes[4] === 0xa1 && bytes[5] === 0xb1 && bytes[6] === 0x1a && bytes[7] === 0xe1;
  if (!isXlsx && !isXls) {
    return [{ json: { ...base, outcome: 'rejected', reasonCode: 'ATTACHMENT_SIGNATURE_INVALID', idempotencyKey: buildKey(attachmentName, size, contentHash) } }];
  }
}

return [{
  json: {
    ...base,
    outcome: 'process',
    reasonCode: null,
    idempotencyKey: buildKey(attachmentName, size, contentHash),
    attachmentName,
    attachmentSize: size,
    binaryKey,
    pollCount: 0,
    pollDeadline: 0
  },
  binary: { [binaryKey]: attachment }
}];

// Решение по реестру: upload / poll / notify / notify-error / done.
const filter = $('Отфильтровать письмо').first().json;
const record = $json && $json.data ? $json.data : null;

if (!record || !record.idempotency_key) {
  return [{ json: { ...filter, action: 'upload' } }];
}
if (record.state === 'completed' && record.run_id) {
  return [{
    json: {
      ...filter,
      action: record.notification_sent_at ? 'done' : 'notify',
      runId: record.run_id
    }
  }];
}
if (record.run_id && ['received', 'uploading', 'run_created', 'processing'].includes(record.state)) {
  return [{ json: { ...filter, action: 'poll', runId: record.run_id } }];
}
if (record.state === 'failed' && record.run_id) {
  return [{ json: { ...filter, action: 'notify-error', runId: record.run_id, runError: record.error_code } }];
}
return [{ json: { ...filter, action: 'done' } }];

// Ответ загрузки: runId (201 или replay 200) либо ошибка.
const data = $json && $json.data ? $json.data : null;
const passthrough = { ...$json };
delete passthrough.data;
delete passthrough.api_version;
delete passthrough.error;
if (data && data.run_id) {
  return [{
    json: {
      ...passthrough,
      runId: data.run_id,
      uploadReplay: data.idempotent_replay === true,
      uploadError: null
    }
  }];
}
return [{
  json: {
    ...passthrough,
    runId: null,
    uploadReplay: false,
    uploadError: ($json && $json.error && $json.error.code) || 'UPLOAD_FAILED'
  }
}];

// Оценка статуса: completed / failed / wait / timeout (без бесконечного цикла).
const timeoutSeconds = Number($env.MINMAX_POLL_TIMEOUT_SECONDS) || 900;
const data = $json && $json.data ? $json.data : null;
const status = data && data.status ? data.status : null;
const runId = (data && data.run_id) || $json.runId || null;
const pollCount = Number($json.pollCount || 0) + 1;
const now = Date.now();
const pollDeadline = Number($json.pollDeadline || 0) || now + timeoutSeconds * 1000;
let verdict;
if (status === 'completed') verdict = 'completed';
else if (status === 'failed') verdict = 'failed';
else if (!status) verdict = 'timeout';
else verdict = now >= pollDeadline ? 'timeout' : 'wait';
return [{
  json: {
    ...$json,
    runId,
    pollCount,
    pollDeadline,
    verdict,
    runError: data && data.error && data.error.code ? data.error.code : null
  }
}];

// Уведомление владельцу: ссылка на Owner Review, без автоотправки заказа.
const filter = $('Отфильтровать письмо').first().json;
const summaryResponse = $('Сводка run').first().json;
const itemsResponse = $('Счётчики решений').first().json;
const summary = summaryResponse && summaryResponse.data ? summaryResponse.data : {};
const itemsData = itemsResponse && itemsResponse.data ? itemsResponse.data : {};
const decisions = itemsData.owner_decisions || {};
const firstItem = Array.isArray(itemsData.items) && itemsData.items.length > 0 ? itemsData.items[0] : {};
const runId = $json.runId || summary.run_id || filter.runId;
const uiBase = String($env.MINMAX_OWNER_UI_BASE_URL || 'http://localhost:3210').replace(/\/$/, '');
const link = uiBase + '/?runId=' + runId;
const financial = summary.financial || {};
const lines = [
  'Отчёт Min/Max обработан AI-закупщиком.',
  '',
  'Поставщик: ' + (firstItem.supplier || '—'),
  'Файл: ' + (filter.attachmentName || '—'),
  'Дата письма: ' + (filter.receivedDate || '—'),
  'Run: ' + runId,
  'Рекомендация: ' + (financial.recommendation || '—'),
  'Позиций в отчёте: ' + (summary.sku_count ?? '—'),
  'Требуют решения владельца: ' + (decisions.needs_decision ?? 0),
  'Финансовый статус: ' + (financial.status || '—'),
  '',
  'Открыть проверку владельца: ' + link,
  '',
  'Заказ поставщику автоматически не отправляется.'
];
return [{
  json: {
    ...$json,
    runId,
    notifyTo: String($env.MINMAX_NOTIFY_EMAIL || ''),
    notifyFrom: String($env.MINMAX_SMTP_FROM || $env.MINMAX_NOTIFY_EMAIL || ''),
    notifySubject: 'Min/Max: отчёт обработан (' + runId + ')',
    notifyText: lines.join('\n')
  }
}];

// Письмо об ошибке: письмо НЕ отмечается успешным, дубликат run невозможен.
const filter = $('Отфильтровать письмо').first().json;
const reasonCode = $json.uploadError || $json.runError || $json.reasonCode || ($json.verdict === 'timeout' ? 'POLL_TIMEOUT' : 'UNKNOWN_ERROR');
const lines = [
  'AI-закупщик не смог обработать письмо Min/Max.',
  '',
  'Файл: ' + (filter.attachmentName || '—'),
  'Письмо UID: ' + (filter.messageUid || '—'),
  'Код ошибки: ' + reasonCode,
  'Idempotency key: ' + (filter.idempotencyKey || '—'),
  '',
  'Письмо НЕ отмечено как успешно обработанное.',
  'Повторная обработка безопасна: дубликат run не будет создан (idempotency key).'
];
return [{
  json: {
    ...$json,
    errorCode: reasonCode,
    notifyTo: String($env.MINMAX_NOTIFY_EMAIL || ''),
    notifyFrom: String($env.MINMAX_SMTP_FROM || $env.MINMAX_NOTIFY_EMAIL || ''),
    notifySubject: 'Min/Max: ошибка обработки письма (' + reasonCode + ')',
    notifyText: lines.join('\n')
  }
}];
